) AS t(province,city,name,slug,category,description,address,latitude,longitude,rating,price_min,price_max,opening_hours,best_time,facilities,tags,featured)
)
INSERT INTO destinations(city_id,name,slug,category,description,address,latitude,longitude,rating,ticket_price_min,ticket_price_max,opening_hours,best_time,facilities,tags,featured)
SELECT c.id,t.name,t.slug,t.category,t.description,t.address,t.latitude::numeric,t.longitude::numeric,t.rating,t.price_min,t.price_max,t.opening_hours,t.best_time,to_jsonb(t.facilities),to_jsonb(t.tags),t.featured
FROM data t JOIN provinces p ON p.name=t.province JOIN cities c ON c.name=t.city AND c.province_id=p.id
ON CONFLICT (slug) DO NOTHING;
